-- v2: accounts/ownership, Decimal money, date-only due/start dates.
-- Generated by `prisma migrate diff`, then hand-edited to preserve existing data:
--   * ownerId columns are added nullable, back-filled with the first (existing) user, then made NOT NULL.
--   * Float -> DECIMAL(12,2) uses an explicit ROUND(x::numeric, 2) (nearest paisa).
--   * timestamp -> DATE maps each value to its Asia/Kolkata calendar date
--     (stored values are UTC; 00:00 UTC -> same day, 18:30 UTC -> next day).
-- Verify with scripts/migration-snapshot.js before/after: counts and sums must be identical.
BEGIN;

-- User: roles and flags. Existing user(s) become ADMIN.
ALTER TABLE "User" ADD COLUMN     "active" BOOLEAN NOT NULL DEFAULT true,
ADD COLUMN     "mustChangePassword" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "payerId" INTEGER,
ADD COLUMN     "role" TEXT NOT NULL DEFAULT 'MEMBER';
UPDATE "User" SET "role" = 'ADMIN';
CREATE UNIQUE INDEX "User_payerId_key" ON "User"("payerId");

-- Ownership: nullable -> back-fill -> NOT NULL.
ALTER TABLE "Borrower"          ADD COLUMN "ownerId" INTEGER;
ALTER TABLE "Loan"              ADD COLUMN "ownerId" INTEGER;
ALTER TABLE "InterestRecord"    ADD COLUMN "ownerId" INTEGER;
ALTER TABLE "Payment"           ADD COLUMN "ownerId" INTEGER;
ALTER TABLE "PaymentAllocation" ADD COLUMN "ownerId" INTEGER;
UPDATE "Borrower"          SET "ownerId" = (SELECT id FROM "User" ORDER BY id LIMIT 1);
UPDATE "Loan"              SET "ownerId" = (SELECT id FROM "User" ORDER BY id LIMIT 1);
UPDATE "InterestRecord"    SET "ownerId" = (SELECT id FROM "User" ORDER BY id LIMIT 1);
UPDATE "Payment"           SET "ownerId" = (SELECT id FROM "User" ORDER BY id LIMIT 1);
UPDATE "PaymentAllocation" SET "ownerId" = (SELECT id FROM "User" ORDER BY id LIMIT 1);
ALTER TABLE "Borrower"          ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "Loan"              ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "InterestRecord"    ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "Payment"           ALTER COLUMN "ownerId" SET NOT NULL;
ALTER TABLE "PaymentAllocation" ALTER COLUMN "ownerId" SET NOT NULL;

-- Money: Float -> DECIMAL(12,2), rounded to the paisa.
ALTER TABLE "Loan"
  ALTER COLUMN "principal"       TYPE DECIMAL(12,2) USING ROUND("principal"::numeric, 2),
  ALTER COLUMN "monthlyInterest" TYPE DECIMAL(12,2) USING ROUND("monthlyInterest"::numeric, 2);
ALTER TABLE "InterestRecord"
  ALTER COLUMN "amount"     TYPE DECIMAL(12,2) USING ROUND("amount"::numeric, 2),
  ALTER COLUMN "paidAmount" TYPE DECIMAL(12,2) USING ROUND("paidAmount"::numeric, 2);
ALTER TABLE "Payment"
  ALTER COLUMN "amount" TYPE DECIMAL(12,2) USING ROUND("amount"::numeric, 2);
ALTER TABLE "PaymentAllocation"
  ALTER COLUMN "amount" TYPE DECIMAL(12,2) USING ROUND("amount"::numeric, 2);

-- Dates: timestamp (UTC) -> IST calendar date. @@unique([loanId, dueDate]) is kept (rebuilt by the type change).
ALTER TABLE "Loan"
  ALTER COLUMN "startDate" TYPE DATE USING (("startDate" AT TIME ZONE 'UTC') AT TIME ZONE 'Asia/Kolkata')::date;
ALTER TABLE "InterestRecord"
  ALTER COLUMN "dueDate" TYPE DATE USING (("dueDate" AT TIME ZONE 'UTC') AT TIME ZONE 'Asia/Kolkata')::date;

-- Indexes and foreign keys for ownership.
CREATE INDEX "Borrower_ownerId_idx" ON "Borrower"("ownerId");
CREATE INDEX "Loan_ownerId_idx" ON "Loan"("ownerId");
CREATE INDEX "InterestRecord_ownerId_idx" ON "InterestRecord"("ownerId");
CREATE INDEX "Payment_ownerId_idx" ON "Payment"("ownerId");
CREATE INDEX "PaymentAllocation_ownerId_idx" ON "PaymentAllocation"("ownerId");
ALTER TABLE "Borrower" ADD CONSTRAINT "Borrower_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Loan" ADD CONSTRAINT "Loan_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "InterestRecord" ADD CONSTRAINT "InterestRecord_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Payment" ADD CONSTRAINT "Payment_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "PaymentAllocation" ADD CONSTRAINT "PaymentAllocation_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

COMMIT;
